import{_ as e,o as n,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"Nginx 配置详解","description":"以官方文档为准，逐指令讲清语法、取值、上下文、继承规则与常见误配。","frontmatter":{"title":"Nginx 配置详解","description":"以官方文档为准，逐指令讲清语法、取值、上下文、继承规则与常见误配。","source":"https://daiw.org/manual/nginx"},"headers":[],"relativePath":"manual/tools/nginx/index.md","filePath":"manual/tools/nginx/index.md"}'),o={name:"manual/tools/nginx/index.md"};function s(d,t,i,l,g,c){return n(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="nginx-配置详解" tabindex="-1">Nginx 配置详解 <a class="header-anchor" href="#nginx-配置详解" aria-label="Permalink to &quot;Nginx 配置详解&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/nginx" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David · 原文更新于 2026-11-06</p></blockquote><p>本专栏<strong>逐指令</strong>解析 nginx 配置：每条指令的语法、默认值、可用上下文、取值含义，以及配错时会发生什么。</p><p>不讲「nginx 是什么」，不讲安装教程，只讲<strong>配置文件里的每一行到底是什么意思</strong>。</p><h2 id="版本基准" tabindex="-1">版本基准 <a class="header-anchor" href="#版本基准" aria-label="Permalink to &quot;版本基准&quot;">​</a></h2><p>以 <a href="https://nginx.org/en/docs/" target="_blank" rel="noreferrer">nginx.org 官方文档</a>为准，快照于 <strong>2026-11-06</strong>：</p><table tabindex="0"><thead><tr><th>分支</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>stable</strong></td><td><strong>1.30.6</strong></td><td>生产推荐。第二段是<strong>偶数</strong>，只收高危修复，不加新特性</td></tr><tr><td><strong>mainline</strong></td><td><strong>1.31.8</strong></td><td>活跃开发分支，新特性先进这里。第二段是<strong>奇数</strong></td></tr></tbody></table><p>nginx 的版本号规则与多数项目相反：<strong>偶数是稳定分支，奇数是主线</strong>。<code>1.30.x</code> 稳定、<code>1.31.x</code> 主线。官方实际推荐多数场景用 mainline——它包含全部修复且质量长期稳定，stable 只是变更更保守。</p><p>本专栏标注指令时会注明「x.y.z 起可用」，遇到较新特性会提示所需版本。</p><h2 id="文档怎么读" tabindex="-1">文档怎么读 <a class="header-anchor" href="#文档怎么读" aria-label="Permalink to &quot;文档怎么读&quot;">​</a></h2><p>nginx 官方文档按<strong>模块</strong>组织，每个模块一页，页内列出该模块的全部指令。三类模块：</p><table tabindex="0"><thead><tr><th>前缀</th><th>数量</th><th>作用域</th></tr></thead><tbody><tr><td><code>ngx_core_module</code> 等</td><td>4</td><td>主上下文与全局</td></tr><tr><td><code>ngx_http_*</code></td><td>80+</td><td>HTTP 处理</td></tr><tr><td><code>ngx_stream_*</code></td><td>20+</td><td>TCP/UDP 代理</td></tr><tr><td><code>ngx_mail_*</code></td><td>7</td><td>邮件代理</td></tr></tbody></table><p>每条指令在文档里都有固定的三行元信息，本专栏沿用这个格式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    directive_name value [value...];</span></span>
<span class="line"><span>默认:    directive_name default;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>「上下文」是最容易被忽略却最重要的一行</strong>——它决定这条指令能写在哪，写错位置轻则不生效，重则 nginx 起不来。</p><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><ul><li><strong>第 0 部分 · 基础</strong>——配置语法、指令与上下文、继承规则、请求处理流程。<strong>必读</strong>，后面所有章节都建立在这四篇之上。</li><li><strong>第 1 部分 · 核心指令</strong>——<code>ngx_core_module</code>、server 与 listen、location 匹配、root/alias/try_files、变量。</li><li><strong>第 2 部分 · 代理与上游</strong>——proxy、upstream 负载均衡、FastCGI/uWSGI/gRPC。</li><li><strong>第 3 部分 · TLS 与协议</strong>——ssl 模块、HTTP/2 与 HTTP/3。</li><li><strong>第 4 部分 · 性能</strong>——缓存、压缩、静态文件与连接调优。</li><li><strong>第 5 部分 · 访问控制</strong>——access/auth、限流限速。</li><li><strong>第 6 部分 · 日志与重写</strong>——log_format、rewrite/return/if、map/geo。</li><li><strong>第 7 部分 · stream 与收尾</strong>——TCP/UDP 代理、常见误配速查。</li></ul><p>从 <a href="/Front2Full/manual/tools/nginx/config-syntax">配置文件语法</a> 开始。</p><h2 id="与站内其他专栏的关系" tabindex="-1">与站内其他专栏的关系 <a class="header-anchor" href="#与站内其他专栏的关系" aria-label="Permalink to &quot;与站内其他专栏的关系&quot;">​</a></h2><p>配置里大量出现 HTTP 概念（<code>Host</code>、<code>ETag</code>、<code>Cache-Control</code>、<code>Range</code>、<code>Connection</code>）。不清楚这些字段的精确语义时，回查：</p><ul><li><a href="https://daiw.org/manual/http11" target="_blank" rel="noreferrer">《HTTP/1.1 协议详解》</a>——字段语义、状态码、缓存与条件请求。</li><li><a href="https://daiw.org/manual/http2-3" target="_blank" rel="noreferrer">《HTTP/2 与 HTTP/3 协议详解》</a>——<code>listen ... http2</code> / <code>quic</code> 背后的协议差异。</li></ul>`,21)])])}const u=e(o,[["render",s]]);export{h as __pageData,u as default};
